const groups={create:{heading:'Less paper. More possibilities.',copy:'Turn a paper document or a handful of photos into a PDF you can keep, organize, and share.',items:[['⌗','Scan Document'],['▧','Images to PDF']]},edit:{heading:'Every page, in its place.',copy:'Bring documents together, keep the pages you need, or make a smaller PDF copy for sharing.',items:[['⋈','Merge PDFs'],['↓','Compress PDF'],['▱','Extract Pages'],['⑂','Split PDF'],['−','Delete Pages']]},text:{heading:'Make your documents work harder.',copy:'Make text selectable with OCR, or remove author and location metadata before sharing your PDF.',items:[['T','Live OCR'],['✳','Strip Metadata']]},secure:{heading:'The finishing touch. And a lock.',copy:'Add your signature, create a password-protected copy, or unlock a document using its existing password.',items:[['〰','Sign PDF'],['⌑','Protect PDF'],['↗','Remove Password']]}};
const tabs=[...document.querySelectorAll('[role=tab]')],panel=document.querySelector('#tool-panel');function select(tab){const g=groups[tab.dataset.group];tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});panel.setAttribute('aria-labelledby',tab.id);panel.innerHTML=`<div class="tool-description"><small>${tab.textContent.trim().toUpperCase()}</small><h3>${g.heading}</h3><p>${g.copy}</p></div><div class="tool-items">${g.items.map(([icon,title])=>`<div class="tool-item"><span aria-hidden="true">${icon}</span>${title}</div>`).join('')}</div>`}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();select(tabs[n]);tabs[n].focus()}})});select(tabs[0]);
